import React, { useRef, useEffect } from 'react';

interface VisualizerProps {
  analyser: AnalyserNode | null;
  isPlaying: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ analyser, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number>();

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !analyser) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const draw = () => {
      animationRef.current = requestAnimationFrame(draw);

      analyser.getByteFrequencyData(dataArray);

      const width = canvas.width;
      const height = canvas.height;

      ctx.clearRect(0, 0, width, height);

      // Draw background
      // ctx.fillStyle = 'rgba(15, 23, 42, 0)'; // Transparent
      // ctx.fillRect(0, 0, width, height);

      const barWidth = (width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        barHeight = dataArray[i] / 2; // Scale down slightly

        // Dynamic gradient based on height
        const gradient = ctx.createLinearGradient(0, height, 0, height - barHeight);
        gradient.addColorStop(0, '#6366f1'); // Indigo 500
        gradient.addColorStop(1, '#a855f7'); // Purple 500

        ctx.fillStyle = gradient;

        // Rounded tops
        ctx.beginPath();
        ctx.roundRect(x, height - barHeight, barWidth, barHeight, [4, 4, 0, 0]);
        ctx.fill();

        x += barWidth + 1;
      }
    };

    if (isPlaying) {
      draw();
    } else {
      // Clear when stopped
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      cancelAnimationFrame(animationRef.current!);
    }

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [analyser, isPlaying]);

  return (
    <canvas
      ref={canvasRef}
      width={600}
      height={150}
      className="w-full h-32 md:h-40 rounded-lg bg-slate-900/50"
    />
  );
};

export default Visualizer;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { generateSpeech } from './services/geminiService';
import { decodeAudioData, decodeBase64 } from './utils/audioUtils';
import VoiceSelector from './components/VoiceSelector';
import Visualizer from './components/Visualizer';
import { VoiceName, Language } from './types';
import { GoogleGenAI } from '@google/genai'; // Keeping this to ensure import is valid as per prompt rules, though used in service.

const SAMPLE_TEXT_ENGLISH = "The quick brown fox jumps over the lazy dog. Voice synthesis is fascinating!";
const SAMPLE_TEXT_TAMIL = "வணக்கம். நான் உங்கள் மெய்நிகர் உதவியாளர். இன்று நான் உங்களுக்கு எப்படி உதவ முடியும்?";

const App: React.FC = () => {
  const [text, setText] = useState<string>(SAMPLE_TEXT_TAMIL);
  const [selectedVoice, setSelectedVoice] = useState<VoiceName>(VoiceName.Kore);
  const [selectedLanguage, setSelectedLanguage] = useState<Language>(Language.Tamil);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Audio Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const audioBufferRef = useRef<AudioBuffer | null>(null);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null); // State for visualizer

  const initAudioContext = () => {
    if (!audioContextRef.current) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      audioContextRef.current = new AudioCtx({ sampleRate: 24000 });

      const analyzerNode = audioContextRef.current.createAnalyser();
      analyzerNode.fftSize = 256;
      analyserRef.current = analyzerNode;
      setAnalyser(analyzerNode);
    }

    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;

    // Check for API Key presence (Mock check as we assume process.env.API_KEY is there)
    if (!process.env.API_KEY) {
      setError("API Key is missing. Please check your environment variables.");
      return;
    }

    setIsLoading(true);
    setError(null);
    stopAudio(); // Stop previous if any

    try {
      initAudioContext();

      const base64Audio = await generateSpeech(text, selectedVoice);
      const rawBytes = decodeBase64(base64Audio);

      if (audioContextRef.current) {
        const buffer = await decodeAudioData(rawBytes, audioContextRef.current, 24000, 1);
        audioBufferRef.current = buffer;
        playAudio(buffer);
      }
    } catch (err: any) {
      setError(err.message || "Failed to generate speech");
    } finally {
      setIsLoading(false);
    }
  };

  const playAudio = (buffer: AudioBuffer) => {
    if (!audioContextRef.current || !analyserRef.current) return;

    // Disconnect old source
    if (sourceNodeRef.current) {
      try {
        sourceNodeRef.current.stop();
        sourceNodeRef.current.disconnect();
      } catch (e) { /* ignore */ }
    }

    const source = audioContextRef.current.createBufferSource();
    source.buffer = buffer;

    // Connect Source -> Analyser -> Destination
    source.connect(analyserRef.current);
    analyserRef.current.connect(audioContextRef.current.destination);

    source.onended = () => {
      setIsPlaying(false);
    };

    source.start();
    sourceNodeRef.current = source;
    setIsPlaying(true);
  };

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      try {
        sourceNodeRef.current.stop();
      } catch (e) { /* ignore */ }
      setIsPlaying(false);
    }
  };

  const handleLanguageChange = (lang: Language) => {
    setSelectedLanguage(lang);
    if (lang === Language.Tamil) {
      setText(SAMPLE_TEXT_TAMIL);
    } else {
      setText(SAMPLE_TEXT_ENGLISH);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 font-sans">
      <div className="w-full max-w-4xl space-y-8">

        {/* Header */}
        <div className="text-center">
          <h1 className="text-4xl sm:text-5xl font-extrabold bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 text-transparent bg-clip-text mb-4 pb-1">
            Vocalize AI
          </h1>
          <p className="text-lg text-slate-400 max-w-2xl mx-auto">
            Generate human-realistic speech in English and Tamil powered by Gemini 2.5.
          </p>
        </div>

        {/* Main Card */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl shadow-2xl overflow-hidden p-6 sm:p-8">

          {/* Controls: Language */}
          <div className="flex justify-center space-x-4 mb-8">
            <button
              onClick={() => handleLanguageChange(Language.Tamil)}
              className={`px-6 py-2 rounded-full font-medium transition-colors ${
                selectedLanguage === Language.Tamil 
                  ? 'bg-indigo-600 text-white' 
                  : 'bg-slate-800 text-slate-400 hover:bg-slate-700'
              }`}
            >
              Tamil (தமிழ்)
            </button>
            <button
              onClick={() => handleLanguageChange(Language.English)}
              className={`px-6 py-2 rounded-full font-medium transition-colors ${
                selectedLanguage === Language.English 
                  ? 'bg-indigo-600 text-white' 
                  : 'bg-slate-800 text-slate-400 hover:bg-slate-700'
              }`}
            >
              English
            </button>
          </div>

          {/* Voice Selector */}
          <div className="mb-8">
            <h2 className="text-sm uppercase tracking-wider text-slate-500 font-semibold mb-3">Select Voice</h2>
            <VoiceSelector 
              selectedVoice={selectedVoice} 
              onSelect={setSelectedVoice} 
              disabled={isLoading || isPlaying}
            />
          </div>

          {/* Text Input */}
          <div className="mb-8">
             <h2 className="text-sm uppercase tracking-wider text-slate-500 font-semibold mb-3">Input Text</h2>
             <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              className="w-full h-40 bg-slate-950 border border-slate-700 rounded-xl p-4 text-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none resize-none text-lg leading-relaxed shadow-inner"
              placeholder="Enter text here..."
              disabled={isLoading}
             />
          </div>

          {/* Visualizer & Playback Controls */}
          <div className="bg-slate-950 rounded-xl p-6 border border-slate-800">
             <div className="flex flex-col sm:flex-row items-center justify-between gap-6">

                {/* Visualizer Canvas */}
                <div className="w-full sm:w-2/3 h-32 md:h-40 flex items-center justify-center bg-slate-900/50 rounded-lg overflow-hidden border border-slate-800/50">
                  {isPlaying ? (
                    <Visualizer analyser={analyser} isPlaying={isPlaying} />
                  ) : (
                     <div className="flex items-center space-x-1 h-8">
                       {[...Array(5)].map((_, i) => (
                         <div key={i} className="w-2 bg-slate-700 rounded-full animate-pulse" style={{ height: '50%', animationDelay: `${i * 0.1}s` }} />
                       ))}
                       <span className="ml-3 text-slate-500 text-sm">Ready to Generate</span>
                     </div>
                  )}
                </div>

                {/* Action Button */}
                <div className="w-full sm:w-1/3 flex flex-col space-y-3">
                  {!isPlaying ? (
                    <button
                      onClick={handleGenerate}
                      disabled={isLoading || !text.trim()}
                      className={`
                        w-full py-4 rounded-xl font-bold text-lg shadow-lg transition-all transform hover:-translate-y-1
                        ${isLoading 
                          ? 'bg-slate-700 cursor-not-allowed text-slate-400' 
                          : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white shadow-indigo-500/30'}
                      `}
                    >
                      {isLoading ? (
                        <span className="flex items-center justify-center">
                          <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                          </svg>
                          Generating...
                        </span>
                      ) : (
                        "Generate Speech"
                      )}
                    </button>
                  ) : (
                     <button
                      onClick={stopAudio}
                      className="w-full py-4 rounded-xl font-bold text-lg bg-red-500/10 text-red-500 border border-red-500/50 hover:bg-red-500/20 transition-all"
                    >
                      Stop Playback
                    </button>
                  )}

                  {audioBufferRef.current && !isPlaying && !isLoading && (
                    <button
                      onClick={() => playAudio(audioBufferRef.current!)}
                      className="w-full py-2 rounded-lg text-sm font-medium text-indigo-400 hover:text-indigo-300 hover:bg-slate-800 transition-colors"
                    >
                      Replay Last Generation
                    </button>
                  )}
                </div>
             </div>
          </div>

          {error && (
            <div className="mt-6 p-4 bg-red-900/20 border border-red-800/50 rounded-lg flex items-center text-red-300">
              <svg className="w-5 h-5 mr-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
              {error}
            </div>
          )}

        </div>

        <p className="text-center text-slate-600 text-sm">
          Powered by Gemini 2.5 Flash TTS Preview. Supports multilingual synthesis.
        </p>

      </div>
    </div>
  );
};

export default App;

/**
 * Decodes a base64 string into a raw Uint8Array.
 */
export function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM data (Int16) into an AudioBuffer (Float32).
 * Gemini TTS output is typically 24kHz mono PCM.
 */
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      // Convert Int16 (-32768 to 32767) to Float32 (-1.0 to 1.0)
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

/**
 * Wraps raw PCM data in a WAV container so it can be played by HTMLAudioElement.
 * This allows using playbackRate without pitch shifting (browser default behavior).
 */
export function pcmToWavBlob(pcmData: Uint8Array, sampleRate: number = 24000): Blob {
  const numChannels = 1;
  const bitsPerSample = 16;
  const byteRate = sampleRate * numChannels * (bitsPerSample / 8);
  const blockAlign = numChannels * (bitsPerSample / 8);
  const dataSize = pcmData.length;
  const headerSize = 44;
  const totalSize = headerSize + dataSize;

  const buffer = new ArrayBuffer(totalSize);
  const view = new DataView(buffer);

  // Helper to write string
  const writeString = (view: DataView, offset: number, string: string) => {
    for (let i = 0; i < string.length; i++) {
      view.setUint8(offset + i, string.charCodeAt(i));
    }
  };

  // RIFF chunk descriptor
  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + dataSize, true); // ChunkSize
  writeString(view, 8, 'WAVE');

  // fmt sub-chunk
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true); // Subchunk1Size (16 for PCM)
  view.setUint16(20, 1, true); // AudioFormat (1 for PCM)
  view.setUint16(22, numChannels, true); // NumChannels
  view.setUint32(24, sampleRate, true); // SampleRate
  view.setUint32(28, byteRate, true); // ByteRate
  view.setUint16(32, blockAlign, true); // BlockAlign
  view.setUint16(34, bitsPerSample, true); // BitsPerSample

  // data sub-chunk
  writeString(view, 36, 'data');
  view.setUint32(40, dataSize, true); // Subchunk2Size

  // Write PCM data
  const pcmBytes = new Uint8Array(buffer, headerSize);
  pcmBytes.set(pcmData);

  return new Blob([buffer], { type: 'audio/wav' });
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { generateSpeech } from './services/geminiService';
import { decodeBase64, pcmToWavBlob } from './utils/audioUtils';
import VoiceSelector from './components/VoiceSelector';
import Visualizer from './components/Visualizer';
import { VoiceName, Language } from './types';
import { GoogleGenAI } from '@google/genai';

const SAMPLE_TEXT_ENGLISH = "The quick brown fox jumps over the lazy dog. Voice synthesis is fascinating!";
const SAMPLE_TEXT_TAMIL = "வணக்கம். நான் உங்கள் மெய்நிகர் உதவியாளர். இன்று நான் உங்களுக்கு எப்படி உதவ முடியும்?";

const App: React.FC = () => {
  const [text, setText] = useState<string>(SAMPLE_TEXT_TAMIL);
  const [selectedVoice, setSelectedVoice] = useState<VoiceName>(VoiceName.Kore);
  const [selectedLanguage, setSelectedLanguage] = useState<Language>(Language.Tamil);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState<number>(1.0);
  const [currentBlobUrl, setCurrentBlobUrl] = useState<string | null>(null);

  // Audio Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const mediaSourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);

  const initAudioContext = () => {
    if (!audioContextRef.current) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      audioContextRef.current = new AudioCtx({ sampleRate: 24000 });

      const analyzerNode = audioContextRef.current.createAnalyser();
      analyzerNode.fftSize = 256;
      analyserRef.current = analyzerNode;
      setAnalyser(analyzerNode);
    }

    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }

    // Connect audio element to analyser if not already connected
    if (audioRef.current && audioContextRef.current && !mediaSourceRef.current && analyserRef.current) {
      try {
        mediaSourceRef.current = audioContextRef.current.createMediaElementSource(audioRef.current);
        mediaSourceRef.current.connect(analyserRef.current);
        analyserRef.current.connect(audioContextRef.current.destination);
      } catch (e) {
        console.error("Error creating MediaElementSource:", e);
      }
    }
  };

  useEffect(() => {
    // Update playback rate dynamically if currently playing or ready
    if (audioRef.current) {
      audioRef.current.playbackRate = speed;
    }
  }, [speed]);

  const handleGenerate = async () => {
    if (!text.trim()) return;

    // Check for API Key presence
    if (!process.env.API_KEY) {
      setError("API Key is missing. Please check your environment variables.");
      return;
    }

    setIsLoading(true);
    setError(null);
    stopAudio();

    try {
      // Ensure AudioContext is ready before we need it
      initAudioContext();

      const base64Audio = await generateSpeech(text, selectedVoice);
      const rawBytes = decodeBase64(base64Audio);

      // Convert PCM to WAV Blob
      const wavBlob = pcmToWavBlob(rawBytes, 24000);
      const blobUrl = URL.createObjectURL(wavBlob);

      if (currentBlobUrl) {
        URL.revokeObjectURL(currentBlobUrl);
      }
      setCurrentBlobUrl(blobUrl);

      if (audioRef.current) {
        audioRef.current.src = blobUrl;
        audioRef.current.playbackRate = speed;
        // The play() call will be handled by the user or auto-played below
        try {
          await audioRef.current.play();
          setIsPlaying(true);
        } catch (e) {
          console.warn("Autoplay blocked or failed:", e);
        }
      }

    } catch (err: any) {
      setError(err.message || "Failed to generate speech");
    } finally {
      setIsLoading(false);
    }
  };

  const handleReplay = async () => {
    if (audioRef.current && currentBlobUrl) {
      initAudioContext();
      audioRef.current.currentTime = 0;
      audioRef.current.playbackRate = speed;
      try {
        await audioRef.current.play();
        setIsPlaying(true);
      } catch (e) {
        console.error("Playback failed:", e);
      }
    }
  };

  const stopAudio = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
      setIsPlaying(false);
    }
  };

  const handleLanguageChange = (lang: Language) => {
    setSelectedLanguage(lang);
    if (lang === Language.Tamil) {
      setText(SAMPLE_TEXT_TAMIL);
    } else {
      setText(SAMPLE_TEXT_ENGLISH);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8 font-sans">
      <div className="w-full max-w-4xl space-y-8">

        {/* Header */}
        <div className="text-center">
          <h1 className="text-4xl sm:text-5xl font-extrabold bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 text-transparent bg-clip-text mb-4 pb-1">
            Vocalize AI
          </h1>
          <p className="text-lg text-slate-400 max-w-2xl mx-auto">
            Generate human-realistic speech in English and Tamil powered by Gemini 2.5.
          </p>
        </div>

        {/* Main Card */}
        <div className="bg-slate-900 border border-slate-800 rounded-2xl shadow-2xl overflow-hidden p-6 sm:p-8">

          {/* Controls: Language */}
          <div className="flex justify-center space-x-4 mb-8">
            <button
              onClick={() => handleLanguageChange(Language.Tamil)}
              className={`px-6 py-2 rounded-full font-medium transition-colors ${
                selectedLanguage === Language.Tamil 
                  ? 'bg-indigo-600 text-white' 
                  : 'bg-slate-800 text-slate-400 hover:bg-slate-700'
              }`}
            >
              Tamil (தமிழ்)
            </button>
            <button
              onClick={() => handleLanguageChange(Language.English)}
              className={`px-6 py-2 rounded-full font-medium transition-colors ${
                selectedLanguage === Language.English 
                  ? 'bg-indigo-600 text-white' 
                  : 'bg-slate-800 text-slate-400 hover:bg-slate-700'
              }`}
            >
              English
            </button>
          </div>

          {/* Voice Selector */}
          <div className="mb-6">
            <h2 className="text-sm uppercase tracking-wider text-slate-500 font-semibold mb-3">Select Voice</h2>
            <VoiceSelector 
              selectedVoice={selectedVoice} 
              onSelect={setSelectedVoice} 
              disabled={isLoading || isPlaying}
            />
          </div>

          {/* Speed Control */}
          <div className="mb-8 p-4 bg-slate-800/50 rounded-xl border border-slate-700/50">
             <div className="flex items-center justify-between mb-2">
                <h2 className="text-sm uppercase tracking-wider text-slate-400 font-semibold">Speech Rate</h2>
                <span className="text-indigo-400 font-bold bg-indigo-900/30 px-3 py-1 rounded-full text-sm">{speed}x</span>
             </div>
             <div className="flex items-center gap-4">
                <span className="text-xs text-slate-500">Slower</span>
                <input 
                  type="range" 
                  min="0.5" 
                  max="2.0" 
                  step="0.25" 
                  value={speed}
                  onChange={(e) => setSpeed(parseFloat(e.target.value))}
                  className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                />
                <span className="text-xs text-slate-500">Faster</span>
             </div>
             <div className="flex justify-between text-xs text-slate-500 mt-2 px-1">
                <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(0.5)}>0.5x</span>
                <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(1.0)}>1.0x</span>
                <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(1.5)}>1.5x</span>
                <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(2.0)}>2.0x</span>
             </div>
          </div>

          {/* Text Input */}
          <div className="mb-8">
             <h2 className="text-sm uppercase tracking-wider text-slate-500 font-semibold mb-3">Input Text</h2>
             <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              className="w-full h-40 bg-slate-950 border border-slate-700 rounded-xl p-4 text-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none resize-none text-lg leading-relaxed shadow-inner"
              placeholder="Enter text here..."
              disabled={isLoading}
             />
          </div>

          {/* Visualizer & Playback Controls */}
          <div className="bg-slate-950 rounded-xl p-6 border border-slate-800">
             <div className="flex flex-col sm:flex-row items-center justify-between gap-6">

                {/* Visualizer Canvas */}
                <div className="w-full sm:w-2/3 h-32 md:h-40 flex items-center justify-center bg-slate-900/50 rounded-lg overflow-hidden border border-slate-800/50 relative">
                  {/* Hidden Audio Element */}
                  <audio 
                    ref={audioRef} 
                    className="hidden" 
                    onEnded={() => setIsPlaying(false)} 
                    onPause={() => setIsPlaying(false)}
                    onPlay={() => setIsPlaying(true)}
                    crossOrigin="anonymous"
                  />

                  {isPlaying ? (
                    <Visualizer analyser={analyser} isPlaying={isPlaying} />
                  ) : (
                     <div className="flex items-center space-x-1 h-8">
                       {[...Array(5)].map((_, i) => (
                         <div key={i} className="w-2 bg-slate-700 rounded-full animate-pulse" style={{ height: '50%', animationDelay: `${i * 0.1}s` }} />
                       ))}
                       <span className="ml-3 text-slate-500 text-sm">Ready to Generate</span>
                     </div>
                  )}
                </div>

                {/* Action Button */}
                <div className="w-full sm:w-1/3 flex flex-col space-y-3">
                  {!isPlaying ? (
                    <button
                      onClick={handleGenerate}
                      disabled={isLoading || !text.trim()}
                      className={`
                        w-full py-4 rounded-xl font-bold text-lg shadow-lg transition-all transform hover:-translate-y-1
                        ${isLoading 
                          ? 'bg-slate-700 cursor-not-allowed text-slate-400' 
                          : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white shadow-indigo-500/30'}
                      `}
                    >
                      {isLoading ? (
                        <span className="flex items-center justify-center">
                          <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                          </svg>
                          Generating...
                        </span>
                      ) : (
                        "Generate Speech"
                      )}
                    </button>
                  ) : (
                     <button
                      onClick={stopAudio}
                      className="w-full py-4 rounded-xl font-bold text-lg bg-red-500/10 text-red-500 border border-red-500/50 hover:bg-red-500/20 transition-all"
                    >
                      Stop Playback
                    </button>
                  )}

                  {currentBlobUrl && !isPlaying && !isLoading && (
                    <button
                      onClick={handleReplay}
                      className="w-full py-2 rounded-lg text-sm font-medium text-indigo-400 hover:text-indigo-300 hover:bg-slate-800 transition-colors"
                    >
                      Replay Last Generation
                    </button>
                  )}
                </div>
             </div>
          </div>

          {error && (
            <div className="mt-6 p-4 bg-red-900/20 border border-red-800/50 rounded-lg flex items-center text-red-300">
              <svg className="w-5 h-5 mr-3 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
              {error}
            </div>
          )}

        </div>

        <p className="text-center text-slate-600 text-sm">
          Powered by Gemini 2.5 Flash TTS Preview. Supports multilingual synthesis.
        </p>

      </div>
    </div>
  );
};

