export interface TextToken {
  text: string;
  isWord: boolean;
  id: number;
  start?: number;
  end?: number;
}

/**
 * Splits text into tokens (words and separators) and assigns estimated timestamps
 * based on the character length of words relative to the total duration.
 */
export const processTextForTiming = (text: string, totalDuration: number): TextToken[] => {
  // Regex explanation:
  // ([^\w\u0B80-\u0BFF]+) matches one or more characters that are NOT (English word chars OR Tamil chars).
  // This effectively splits by separators while capturing them.
  const parts = text.split(/([^\w\u0B80-\u0BFF]+)/); 

  const tokens: TextToken[] = [];
  let charCount = 0;

  // First pass: Create tokens and count total "speakable" characters
  parts.forEach((part, index) => {
     if (!part) return;

     // Check if part contains alphanumeric or Tamil chars (rough heuristic for "speakable" content)
     const isWord = /[\w\u0B80-\u0BFF]/.test(part);

     if (isWord) {
         charCount += part.length;
     }

     tokens.push({ 
       text: part, 
       isWord, 
       id: index 
     });
  });

  // Second pass: Distribute duration among words
  let currentTime = 0;
  tokens.forEach(token => {
      if (token.isWord) {
          // Calculate duration proportional to length
          // We assume a linear speaking rate for estimation
          const duration = (token.text.length / charCount) * totalDuration;

          token.start = currentTime;
          token.end = currentTime + duration;

          currentTime += duration;
      }
  });

  return tokens;
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { generateSpeech } from './services/geminiService';
import { decodeBase64, pcmToWavBlob } from './utils/audioUtils';
import { processTextForTiming, TextToken } from './utils/textUtils';
import VoiceSelector from './components/VoiceSelector';
import Visualizer from './components/Visualizer';
import { VoiceName, Language, SAMPLE_TEXTS, SampleText } from './types';

const App: React.FC = () => {
  // State
  const [text, setText] = useState<string>(SAMPLE_TEXTS[2].content); // Default to Tamil Greeting
  const [selectedVoice, setSelectedVoice] = useState<VoiceName>(VoiceName.Kore);
  const [selectedLanguage, setSelectedLanguage] = useState<Language>(Language.Tamil);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState<number>(1.0);
  const [currentBlobUrl, setCurrentBlobUrl] = useState<string | null>(null);

  // Highlight / Reader Mode State
  const [isReaderMode, setIsReaderMode] = useState(false);
  const [tokens, setTokens] = useState<TextToken[]>([]);
  const [activeTokenId, setActiveTokenId] = useState<number | null>(null);
  const [hasGeneratedAudio, setHasGeneratedAudio] = useState(false);

  // Audio Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const mediaSourceRef = useRef<MediaElementAudioSourceNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  const initAudioContext = () => {
    if (!audioContextRef.current) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      audioContextRef.current = new AudioCtx({ sampleRate: 24000 });

      const analyzerNode = audioContextRef.current.createAnalyser();
      analyzerNode.fftSize = 256;
      analyserRef.current = analyzerNode;
      setAnalyser(analyzerNode);
    }

    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }

    if (audioRef.current && audioContextRef.current && !mediaSourceRef.current && analyserRef.current) {
      try {
        mediaSourceRef.current = audioContextRef.current.createMediaElementSource(audioRef.current);
        mediaSourceRef.current.connect(analyserRef.current);
        analyserRef.current.connect(audioContextRef.current.destination);
      } catch (e) {
        console.error("Error creating MediaElementSource:", e);
      }
    }
  };

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.playbackRate = speed;
    }
  }, [speed]);

  // Animation Loop for Highlighting
  const updateHighlight = useCallback(() => {
    if (audioRef.current && !audioRef.current.paused) {
      const currentTime = audioRef.current.currentTime;

      // Find the active token
      const active = tokens.find(t => 
        t.isWord && 
        t.start !== undefined && 
        t.end !== undefined && 
        currentTime >= t.start && 
        currentTime < t.end
      );

      if (active) {
        setActiveTokenId(active.id);
      } else if (currentTime >= (tokens[tokens.length - 1]?.end || 0)) {
        setActiveTokenId(null);
      }

      animationFrameRef.current = requestAnimationFrame(updateHighlight);
    }
  }, [tokens]);

  useEffect(() => {
    if (isPlaying) {
      animationFrameRef.current = requestAnimationFrame(updateHighlight);
    } else {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      setActiveTokenId(null);
    }
    return () => {
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    };
  }, [isPlaying, updateHighlight]);

  const handleGenerate = async () => {
    if (!text.trim()) return;
    if (!process.env.API_KEY) {
      setError("API Key is missing.");
      return;
    }

    setIsLoading(true);
    setError(null);
    stopAudio();
    setHasGeneratedAudio(false);

    try {
      initAudioContext();

      const base64Audio = await generateSpeech(text, selectedVoice);
      const rawBytes = decodeBase64(base64Audio);

      // Process WAV
      const wavBlob = pcmToWavBlob(rawBytes, 24000);
      const blobUrl = URL.createObjectURL(wavBlob);

      // Calculate Duration for Timings (Estimate based on PCM size)
      // 24kHz * 16bit * 1ch = 48000 bytes/sec
      const estimatedDuration = rawBytes.length / 48000;
      const calculatedTokens = processTextForTiming(text, estimatedDuration);
      setTokens(calculatedTokens);

      if (currentBlobUrl) {
        URL.revokeObjectURL(currentBlobUrl);
      }
      setCurrentBlobUrl(blobUrl);
      setHasGeneratedAudio(true);

      // Auto-switch to reader mode
      setIsReaderMode(true);

      if (audioRef.current) {
        audioRef.current.src = blobUrl;
        audioRef.current.playbackRate = speed;
        try {
          await audioRef.current.play();
          setIsPlaying(true);
        } catch (e) {
          console.warn("Autoplay blocked:", e);
        }
      }

    } catch (err: any) {
      setError(err.message || "Failed to generate speech");
    } finally {
      setIsLoading(false);
    }
  };

  const handleReplay = async () => {
    if (audioRef.current && currentBlobUrl) {
      initAudioContext();
      audioRef.current.currentTime = 0;
      audioRef.current.playbackRate = speed;
      setIsReaderMode(true);
      try {
        await audioRef.current.play();
        setIsPlaying(true);
      } catch (e) {
        console.error("Playback failed:", e);
      }
    }
  };

  const handleDownload = () => {
    if (currentBlobUrl) {
      const a = document.createElement('a');
      a.href = currentBlobUrl;
      a.download = `vocalize-${selectedVoice}-${Date.now()}.wav`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }
  };

  const stopAudio = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
      setIsPlaying(false);
    }
  };

  const handleLanguageChange = (lang: Language) => {
    setSelectedLanguage(lang);
    // Find first sample text for this language
    const defaultSample = SAMPLE_TEXTS.find(s => s.language === lang);
    if (defaultSample) setText(defaultSample.content);
  };

  const handleSampleSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const sampleId = e.target.value;
    const sample = SAMPLE_TEXTS.find(s => s.id === sampleId);
    if (sample) {
      setText(sample.content);
      setSelectedLanguage(sample.language);
      setHasGeneratedAudio(false);
      setIsReaderMode(false);
    }
  };

  return (
    <div className="min-h-screen text-slate-100 flex flex-col font-sans selection:bg-indigo-500/30 selection:text-indigo-200">

      {/* Navbar */}
      <nav className="sticky top-0 z-50 backdrop-blur-xl bg-slate-950/70 border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-500/20">
               <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
               </svg>
             </div>
             <span className="text-xl font-bold tracking-tight bg-gradient-to-r from-white to-slate-400 bg-clip-text text-transparent">
               Vocalize AI
             </span>
          </div>
          <div className="text-xs font-medium px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-300">
            Gemini 2.5 Preview
          </div>
        </div>
      </nav>

      <main className="flex-grow max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">

          {/* Left Panel: Configuration */}
          <div className="lg:col-span-4 space-y-6">
            <div className="bg-slate-900/40 backdrop-blur-md border border-slate-800/50 rounded-2xl p-6 shadow-xl">

              <div className="mb-6">
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-3">Language & Samples</label>

                {/* Language Toggle */}
                <div className="flex p-1 bg-slate-950/50 rounded-xl border border-slate-800/50 mb-4">
                  <button
                    onClick={() => handleLanguageChange(Language.Tamil)}
                    className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                      selectedLanguage === Language.Tamil 
                        ? 'bg-slate-800 text-white shadow-sm' 
                        : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    Tamil
                  </button>
                  <button
                    onClick={() => handleLanguageChange(Language.English)}
                    className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
                      selectedLanguage === Language.English 
                        ? 'bg-slate-800 text-white shadow-sm' 
                        : 'text-slate-400 hover:text-slate-200'
                    }`}
                  >
                    English
                  </button>
                </div>

                {/* Sample Dropdown */}
                <select 
                  onChange={handleSampleSelect}
                  className="w-full bg-slate-950/50 border border-slate-800/50 text-slate-300 text-sm rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500/50 hover:bg-slate-900/50 transition-colors"
                >
                  <option value="">Load a Sample Text...</option>
                  {SAMPLE_TEXTS.map(sample => (
                    <option key={sample.id} value={sample.id}>
                      {sample.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="mb-6">
                <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold mb-3">Voice Model</label>
                <VoiceSelector 
                  selectedVoice={selectedVoice} 
                  onSelect={setSelectedVoice} 
                  disabled={isLoading || isPlaying}
                />
              </div>

              <div>
                <div className="flex items-center justify-between mb-3">
                  <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold">Speech Rate</label>
                  <span className="text-xs font-mono bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded">{speed.toFixed(2)}x</span>
                </div>
                <div className="relative flex items-center w-full h-10">
                   <input 
                      type="range" 
                      min="0.5" 
                      max="2.0" 
                      step="0.1" 
                      value={speed}
                      onChange={(e) => setSpeed(parseFloat(e.target.value))}
                      className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500 focus:outline-none focus:ring-2 focus:ring-indigo-500/50"
                    />
                </div>
                <div className="flex justify-between text-[10px] text-slate-500 font-medium">
                  <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(0.5)}>0.5x</span>
                  <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(1.0)}>1.0x</span>
                  <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(1.5)}>1.5x</span>
                  <span className="cursor-pointer hover:text-indigo-400" onClick={() => setSpeed(2.0)}>2.0x</span>
                </div>
              </div>

            </div>
          </div>

          {/* Right Panel: Output & Controls */}
          <div className="lg:col-span-8 flex flex-col space-y-6">

            {/* Input / Reader Area */}
            <div className="relative flex-grow min-h-[300px] bg-slate-900/40 backdrop-blur-md border border-slate-800/50 rounded-2xl p-1 shadow-xl group focus-within:ring-2 focus-within:ring-indigo-500/30 transition-all flex flex-col">

               {/* Toolbar */}
               {hasGeneratedAudio && (
                 <div className="absolute top-3 right-3 z-10 flex space-x-2">
                   <button 
                    onClick={() => setIsReaderMode(!isReaderMode)}
                    className="px-3 py-1.5 rounded-lg bg-slate-800/80 backdrop-blur text-xs font-medium text-indigo-300 border border-indigo-500/30 hover:bg-slate-700 transition-all"
                   >
                     {isReaderMode ? 'Edit Text' : 'Reader Mode'}
                   </button>
                 </div>
               )}

               {isReaderMode && hasGeneratedAudio ? (
                 <div className="w-full h-full bg-transparent p-6 text-lg leading-relaxed text-slate-300 overflow-y-auto max-h-[500px] custom-scrollbar rounded-xl">
                   {tokens.map((token) => (
                     <span 
                       key={token.id}
                       className={`
                         transition-all duration-200 rounded px-0.5
                         ${token.id === activeTokenId ? 'bg-indigo-500 text-white shadow-sm font-medium scale-105 inline-block' : ''}
                       `}
                     >
                       {token.text}
                     </span>
                   ))}
                 </div>
               ) : (
                 <textarea
                  value={text}
                  onChange={(e) => {
                    setText(e.target.value);
                    setHasGeneratedAudio(false); // Reset generated state if text changes
                  }}
                  className="w-full h-full bg-transparent p-6 text-lg leading-relaxed text-slate-200 outline-none resize-none placeholder:text-slate-600 rounded-xl"
                  placeholder="Enter text here to synthesize..."
                  disabled={isLoading}
                 />
               )}

               {!isReaderMode && (
                 <div className="absolute bottom-4 right-4 text-xs text-slate-600 pointer-events-none">
                   {text.length} chars
                 </div>
               )}
            </div>

            {/* Visualizer & Actions */}
            <div className="bg-slate-900/40 backdrop-blur-md border border-slate-800/50 rounded-2xl p-6 shadow-xl">

               {/* Visualizer Container */}
               <div className="relative w-full h-40 bg-slate-950/50 rounded-xl overflow-hidden border border-slate-800/50 mb-6 group">
                  <audio 
                    ref={audioRef} 
                    className="hidden" 
                    onEnded={() => {
                      setIsPlaying(false);
                      setActiveTokenId(null);
                    }} 
                    onPause={() => setIsPlaying(false)}
                    onPlay={() => setIsPlaying(true)}
                    crossOrigin="anonymous"
                  />

                  {isPlaying ? (
                    <>
                      <Visualizer analyser={analyser} isPlaying={isPlaying} />
                      <div className="absolute top-3 right-3 flex items-center gap-2">
